def _who(t):
    a=t.get("ages",[]);sk=t["skill"]
    ages=" and ".join({"kids":"kids (with a grown-up)","teens":"teens","adults":"adults"}[x] for x in a) or "makers"
    lvl={"beginner":"total beginners","intermediate":"people who have made something before","advanced":"experienced makers ready for a steep learning curve"}[sk]
    return f"Best for {ages}, and for {lvl}."
def _pc(t):
    P,C=[],[]
    if t["price"]=="free":P.append("Costs nothing to use")
    elif t["price"]=="freemium":P.append("Free tier to start");C.append("Some features need a paid plan")
    else:C.append("Costs money")
    if t["license"]=="open-source":P.append("Open source — free forever, community-run")
    if t["skill"]=="beginner":P.append("Gentle learning curve")
    if t["skill"]=="advanced":C.append("Steep learning curve")
    if len(t["platforms"])>=3:P.append("Runs on "+", ".join(t["platforms"][:4]))
    elif t["platforms"]:C.append("Only on "+", ".join(t["platforms"]))
    if "kids" not in t.get("ages",[]):C.append("Not meant for young kids")
    if t.get("age_note"):C.append("Age rules apply — see below")
    return P or ["Well-known option in its category"],C or ["Few downsides for its audience"]
def TJUMP(ids):return '<nav class="jump" aria-label="On this page"><b>On this page:</b> '+" ".join(f'<a href="#{i}">{n}</a>' for i,n in ids)+'</nav>'
def TOOLX(t):
    P,C=_pc(t);tu=[x for x in TUTS if t["slug"] in x["tools"]];vi=[v for v in VIDS if t["slug"] in v.get("tools",[])][:4]
    pa=[p for p in PATHSD if any(t["slug"] in p["stack"].get(a,[]) for a in ("kids","teens","adults"))][:6]
    learn=("".join(f'<li><a href="../tutorials/{x["slug"]}.html"><b>{E(x["title"])}</b></a> <span class="mut">· {E(x["time"])}</span></li>' for x in tu) or "")+("".join(f'<li><a href="{E(v["url"])}" rel="noopener">{icon("play",14)} {E(v["title"])}</a> <span class="mut">· {E(v["channel"])}</span></li>' for v in vi))
    return f'''<section class="tx"><div class="txgrid"><div class="txc" id="who"><h2>Who it’s for</h2><p>{_who(t)}</p></div><div class="txc" id="cost"><h2>What it costs</h2><p><b>{t["price"].capitalize()}.</b> {PRICE_TXT[t["price"]]}</p></div></div>
<div class="pc" id="pros"><div><h2>Good stuff</h2><ul class="good">{"".join(f"<li>{E(x)}</li>" for x in P)}</ul></div><div><h2>Watch out for</h2><ul class="bad">{"".join(f"<li>{E(x)}</li>" for x in C)}</ul></div></div>
<h2 id="first">Your first steps</h2><ol class="fsteps">{"".join(f"<li>{E(x)}</li>" for x in FIRST[t["category"]])}</ol>
{f'<h2 id="learn">Learn it here</h2><ul class="learn">{learn}</ul>' if learn else '<h2 id="learn">Learn it here</h2><p>Start with the official docs on the <a href="'+E(t["url"])+'" rel="noopener">official site</a>, then try our <a href="../tutorials/">tutorials</a>.</p>'}
{f'<p class="mut">Used in these game paths: '+", ".join(f'<a href="../pathfinder/?q={E(p["title"])}">{E(p["title"])}</a>' for p in pa)+'</p>' if pa else ""}</section>'''
TOOL_JUMP=[("overview","Facts"),("who","Who it’s for"),("cost","Cost"),("pros","Pros & cons"),("first","First steps"),("learn","Learn")]
CHOOSE={"ai":"Pick the assistant you already have an account for. Check the age rules first — several are 13+ or 18+.","engine":"New? Start with an engine marked Beginner. Want 3D or console later? Look at Godot, Unity or Unreal.","art":"For pixel art pick a 2D editor; for 3D models start with Blender. Free assets can skip this step entirely.","audio":"Start by generating simple sound effects, then record or compose once your game plays.","kids":"Pick based on the device you have: browser, tablet, console or PC.","vr":"Check which headset you have first, then match the engine to it.","publish":"For a first game, a free web page is plenty. Stores come later.","learn":"One good course you finish beats ten you start."}
def CATX(k,L):
    top=[t for t in L if t["skill"]=="beginner"][:3] or L[:3]
    return f'''{TJUMP([("start","Start with"),("choose","How to choose"),("all","All tools")])}<section class="startwith" id="start"><h2>Start with one of these</h2><div class="sw3">{"".join(f'<a class="swc" href="../tools/{t["slug"]}.html"><b>{E(t["name"])}</b><span>{E(t["blurb"])}</span><em>{t["price"]} · {SK[t["skill"]]}</em></a>' for t in top)}</div></section>
<div class="note" id="choose">{icon("info")} <b>How to choose:</b> {E(CHOOSE.get(k,""))}</div><h2 id="all">All {len(L)} tools</h2>'''
GLOSS=[("Asset","Any piece of content in a game: images, sounds, music, 3D models, fonts."),("Sprite","A 2D image used for a character or object, often with several frames for animation."),("Tileset / tilemap","A sheet of small square images (tiles) you arrange on a grid to build levels."),("Game engine","Software that handles drawing, physics, input and sound so you can focus on your game (e.g. Godot, Unity)."),("Game loop","The cycle every game repeats: read input, update the world, draw the screen — many times per second."),("Core loop","The main thing the player does over and over, like jump–collect–avoid."),("Prototype","A quick, rough version made to test if an idea is fun."),("MVP","Minimum viable product: the smallest version you could actually release."),("Collision","When two objects touch; engines detect it so you can react (lose a life, pick up a coin)."),("Physics","Simulated gravity, bouncing and pushing."),("Hitbox","The invisible shape used to check collisions, often simpler than the art."),("Scene / level","One screen or area of a game, with its objects."),("Script","Code attached to an object that tells it how to behave."),("Variable","A named value the game remembers, like score or lives."),("Event / signal","A message that something happened (button pressed, enemy hit) that code can react to."),("Frame rate (FPS)","How many times per second the screen updates. 60 is common."),("Export / build","Turning your project into something others can play (a web page, an app, an .exe)."),("Playtest","Watching someone else play your game to find what’s confusing or broken."),("Vibe coding","Making software by describing what you want to an AI assistant and refining its output."),("Prompt","The instructions you type to an AI assistant."),("Single-file HTML game","A whole game in one .html file that runs in any browser."),("Low poly","A 3D style with few polygons — simple, fast and beginner-friendly."),("Pixel art","Art drawn pixel by pixel at small sizes, scaled up for a retro look."),("glTF","A common open file format for 3D models, supported by Blender and Godot."),("CC0","A public-domain style license: use the asset for anything, no credit needed."),("CC BY","A Creative Commons license: free to use if you credit the creator."),("CC BY-NC","Like CC BY but non-commercial: you can’t use it in something you sell."),("Open source","Software whose code is public and free to use, change and share under its license."),("Freemium","Free to start, with paid upgrades."),("Game jam","An event where people make a game in a short time, often around a theme."),("Itch.io","A popular site for publishing indie and small games, including free web games."),("Obby","Roblox slang for an obstacle course game.")]
FAQ=[("I’ve never made anything. Where do I start?","Open the Start here page, pick your age group, and follow the three steps. Plan a tiny game first — one action, one way to win, one way to lose."),("Do I need to know how to code?","No. Scratch, MakeCode Arcade, Roblox Studio templates and AI assistants let you start without writing code from scratch. Learning a little code later helps a lot."),("Is it really free?","Many great tools are free, including Godot, Blender, Scratch and Audacity. Filter the tools directory by “free”. Always check the official site — prices change."),("What age can my kid start?","Many kids start around 6–8 with Scratch or similar block tools, with a grown-up nearby. Check each tool’s age rules; several AI chatbots require 13+ or 18+."),("Which engine should I pick?","For a first 2D game, Godot is free and beginner-friendly. If you already play Roblox or Fortnite, their creator tools are a fun start. Don’t overthink it — finishing a small game matters more."),("Can AI make the whole game for me?","AI can write a working small game, especially a single HTML file, but you still decide what’s fun, test it, and fix problems. Think of it as a fast helper."),("How long does a first game take?","A tiny game can take a weekend. Keep the plan small and add features in version 2."),("Where do I get art and sound?","Use free libraries like Kenney (CC0) and Freesound (check each sound’s license), or make your own. See our free art and free sound pages."),("Can I sell my game?","Usually yes, if every asset you used allows commercial use and you follow each tool’s terms. Avoid CC BY-NC assets in paid games."),("How do I share my game?","For web games, itch.io and GitHub Pages are free. See the “Publish on itch.io” tutorial."),("Is this site sponsored?","Sponsor slots are clearly labeled. Listings and recommendations are not paid placements."),("Does Build Buddy send my messages anywhere?","No. Build Buddy runs entirely in your browser and only uses this site’s own data. Nothing you type leaves your device.")]
